"""Budget-scale stress cases for the submitted engine."""
import sys, json, time, random
sys.path.insert(0,'/workspace/dev'); sys.path.insert(0,'/workspace/submission')
sys.path.insert(0,'/workspace/site')
import ctypes; ctypes.CDLL('/workspace/native/libz.so.1', mode=ctypes.RTLD_GLOBAL)
import harness
harness.setup_env()
import formats, pipeline

PAD = 1514
LEAD = [1100, 1200, 1300]
TAIL = [1400, 1420, 1450, 1480]


def safe(rng, low=1000, high=2000):
    value = rng.randint(low, high)
    return 1513 if value == PAD else value


def discovery_row(seq, cls=0):
    return {'class': cls, 'values': LEAD + list(seq) + TAIL,
            'activation': [0] * len(LEAD) + [1000] * len(seq) + [0] * len(TAIL)}


def validation_row(seq, cls=0, rng=None):
    values = list(seq)
    if rng is not None:
        values = [safe(rng) for _ in range(rng.randint(0, 4))] + values + \
                 [safe(rng) for _ in range(rng.randint(0, 4))]
    return {'class': cls, 'values': values}


def release(rid, **kw):
    base = {'id': rid, 'classes': 1, 'width': 4, 'eps': [1, 1], 'ratio': [0, 1],
            'threshold': [0, 1], 'mode': 'range', 'packet_limit': 200000,
            'idle_us': 10 ** 12, 'discovery': [], 'train': [], 'validation': []}
    base.update(kw)
    return base


def timed(label, request):
    start = time.time()
    out = pipeline.execute(formats.validate(json.loads(json.dumps(request))))
    for cat in out['catalog']:
        print('%-11s %7.1fs %s clusters=%d kept=%d entries=%d frags=%d noise=%d '
              'decisions=%d' % (label, time.time() - start, cat['id'],
                                len(cat['clusters']), len(cat['priority']),
                                cat['entries'], len(cat['fragments']), len(cat['noise']),
                                len(out['decisions'])))
    return out


def stress_clustering():
    """4096 fragments in one class/length group: pairwise neighbourhoods."""
    rng = random.Random(7)
    pool = [[rng.choice([1600, 1601, 1602, 2000, 2001]) for _ in range(4)]
            for _ in range(12)]
    rows = [discovery_row(pool[index % 12]) for index in range(4096)]
    validation = [validation_row(seq, rng=rng) for seq in pool]
    return {'capacity': {'range': 4096, 'exact': 0},
            'releases': [release('m', discovery=rows,
                                 train=[{'class': 0, 'values': seq} for seq in pool],
                                 validation=validation)],
            'blocks': []}


def stress_calibration():
    """2048 distinct kept patterns against 7000 long validation rows."""
    rng = random.Random(11)
    rows = []
    validation = []
    for index in range(1024):
        seq = [1600 + (index % 64), 1600 + (index // 64), 1700, 1701]
        rows.append(discovery_row(seq))
        rows.append(discovery_row(seq))
        validation.append(validation_row(seq, rng=rng))
    for _ in range(6000):
        validation.append({'class': 0, 'values': [safe(rng) for _ in range(120)]})
    rng.shuffle(validation)
    return {'capacity': {'range': 4096, 'exact': 0},
            'releases': [release('m', discovery=rows,
                                 train=[{'class': 0, 'values': [1600, 1600, 1700, 1701]}],
                                 validation=validation)],
            'blocks': []}


def stress_replay():
    """199k packets against a 64-pattern table, mostly non matching."""
    rng = random.Random(13)
    rows = []
    for index in range(64):
        seq = [1600 + index, 1700, 1701, 1702]
        rows.append(discovery_row(seq))
        rows.append(discovery_row(seq))
    blocks = [['install', 'm']]
    for flow in range(185):
        name = 'f%03d' % flow
        blocks.append(['open', name])
        for position in range(1080):
            blocks.append(['packet', name, position, position % 2,
                           rng.choice([86, 87, 100, 148, 186, 187, 148, 149])])
        blocks.append(['close', name])
    return {'capacity': {'range': 4096, 'exact': 0},
            'releases': [release('m', discovery=rows,
                                 train=[{'class': 0, 'values': [1600, 1600, 1700, 1701]}],
                                 validation=[{'class': 0, 'values': [1600, 1700, 1701, 1702]}])],
            'blocks': [blocks]}


def stress_replay_exact():
    """Exact-mode table with 2048 kept patterns and 40k packets."""
    rng = random.Random(29)
    rows = []
    for index in range(1024):
        seq = [1520 + (index % 32), 1520 + (index // 32), 1600, 1601]
        rows.append(discovery_row(seq))
        rows.append(discovery_row(seq))
    blocks = [['install', 'm']]
    for flow in range(40):
        name = 'g%02d' % flow
        blocks.append(['open', name])
        for position in range(1000):
            blocks.append(['packet', name, position, position % 2,
                           rng.choice([6, 7, 80, 81, 86, 87])])
        blocks.append(['close', name])
    return {'capacity': {'range': 0, 'exact': 8192},
            'releases': [release('m', mode='exact', discovery=rows,
                                 train=[{'class': 0, 'values': [1600, 1600, 1700, 1701]}],
                                 validation=[{'class': 0, 'values': [1520, 1520, 1600, 1601]}])],
            'blocks': [blocks]}


def stress_installs():
    releases = []
    for index in range(8):
        rows = []
        for k in range(20):
            seq = [1600 + 3 * k, 1700 + index, 1701, 1702]
            rows.append(discovery_row(seq))
            rows.append(discovery_row(seq))
        releases.append(release('m%d' % index, mode='exact', discovery=rows,
                                train=[{'class': 0, 'values': [1600, 1700, 1701, 1702]}],
                                validation=[{'class': 0, 'values': [1600, 1700 + index,
                                                                    1701, 1702]}]))
    ops = [['install', 'm%d' % (index % 8)] for index in range(2048)]
    return {'capacity': {'range': 4096, 'exact': 12}, 'releases': releases,
            'blocks': [ops]}


def stress_census():
    """Wide interval boxes: the exact census has to clip early."""
    rows = []
    for index in range(500):
        seq = [1000 + index, 2000, 1500, 1800]
        rows.append(discovery_row(seq))
        rows.append(discovery_row([1000 + index, 2001, 1500, 1800]))
    return {'capacity': {'range': 0, 'exact': 8192},
            'releases': [release('m', mode='exact', discovery=rows,
                                 train=[{'class': 0, 'values': [1600, 1700, 1701, 1702]}],
                                 validation=[{'class': 0, 'values': [1000, 2000, 1500, 1800]}])],
            'blocks': []}


def stress_wide():
    rng = random.Random(23)
    rows = []
    validation = []
    for index in range(100):
        seq = [safe(rng, 1000, 2400) for _ in range(4)]
        rows.append(discovery_row(seq))
        rows.append(discovery_row([min(3028, v + 300) for v in seq]))
        validation.append(validation_row(seq, rng=rng))
    return {'capacity': {'range': 4096, 'exact': 8192},
            'releases': [release('m', mode='exact', eps=[600, 1], discovery=rows,
                                 train=[{'class': 0, 'values': [1600, 1700, 1701, 1702]}],
                                 validation=validation)],
            'blocks': []}


CASES = {'clustering': stress_clustering, 'calibration': stress_calibration,
         'replay': stress_replay, 'replayx': stress_replay_exact,
         'installs': stress_installs, 'census': stress_census, 'wide': stress_wide}

if __name__ == '__main__':
    which = sys.argv[1] if len(sys.argv) > 1 else 'all'
    for name, maker in CASES.items():
        if which in ('all', name):
            timed(name, maker())
